using System;using System.IO;using System.Reflection;using System.Collections;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class EnemyFacingCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var world=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);world.BeforeTick(g.Run);g.Run.Tick();world.AfterTick(g.Run,g.ReducedMotion);typeof(InkBattleWorld).GetField("freeze",flags).SetValue(world,0f);g.PresentBattle();var entries=(IDictionary)typeof(InkBattleWorld).GetField("enemies",flags).GetValue(world);int checkedCount=0;foreach(DictionaryEntry entry in entries){var v=entry.Value;var t=v.GetType();var state=(EnemyState)t.GetField("state").GetValue(v);if(state.Kind!=EnemyKind.Fast)continue;var a=(Vector2)t.GetField("previous").GetValue(v);var b=(Vector2)t.GetField("current").GetValue(v);var project=typeof(InkBattleWorld).GetMethod("Project",flags);var direction=(Vector2)project.Invoke(world,new object[]{b})-(Vector2)project.Invoke(world,new object[]{a});if(direction.sqrMagnitude<.000001f)continue;var body=(SpriteRenderer)t.GetField("body").GetValue(v);float expected=Mathf.Atan2(direction.y,direction.x)*Mathf.Rad2Deg;if(Mathf.Abs(Mathf.DeltaAngle(body.transform.localEulerAngles.z,expected))>.1f)throw new Exception("Facing mismatch");checkedCount++;}if(checkedCount==0)throw new Exception("No moving fast enemy");var result=new{checkedCount,passed=true,wave=g.Run.Wave};File.WriteAllText(Path.GetFullPath("../docs/evidence/enemy-facing.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/enemy-ember-battle.png"));return result;}}

